using BusinessPartnerPortal.Api.Data;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Services;
public sealed class DataRetentionWorker(IServiceProvider services,IConfiguration config,ILogger<DataRetentionWorker> logger):BackgroundService{protected override async Task ExecuteAsync(CancellationToken stoppingToken){while(!stoppingToken.IsCancellationRequested){if(int.TryParse(config["DATA_RETENTION_DAYS"],out var days)&&days>0){try{using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var cutoff=DateTimeOffset.UtcNow.AddDays(-days);var old=await db.Documents.Where(x=>x.UploadedAt<cutoff).ToListAsync(stoppingToken);if(old.Count>0){db.Documents.RemoveRange(old);await db.SaveChangesAsync(stoppingToken);logger.LogInformation("Retention policy removed {Count} document payloads older than {Days} days.",old.Count,days);}}catch(Exception ex){logger.LogError(ex,"Retention worker failed.");}}await Task.Delay(TimeSpan.FromHours(24),stoppingToken);}}}
